UPDATE user
SET following_count = following_count + #{increment}, update_time = NOW()
WHERE id = #{userId}

UPDATE user
SET follower_count = follower_count + #{increment}, update_time = NOW()
WHERE id = #{userId}

UPDATE user
SET signature = #{signature}, update_time = NOW()
WHERE id = #{userId}

UPDATE user
SET like_count = IFNULL(like_count, 0) + #{increment}, update_time = NOW()
WHERE id = #{userId}
